        wd_truncated(tree, wd_ei_truncated, "flag")
        return nil
    end
    tree:add(f_flag, tvb(offset, 1))
    v_flag = string.unpack(">I1", tvb:raw(offset, 1))
    offset = offset + 1
    -- If: opt
