        local condition = v_flag
        if condition ~= 0 then
            -- Field: opt
            if not wd_fits(tvb, offset, 1) then
                wd_truncated(tree, wd_ei_truncated, "opt")
                return nil
            end
            tree:add(f_opt, tvb(offset, 1))
            offset = offset + 1
        end
